import pandas as pd

# Load data
sequences = pd.read_csv('sequences.csv')

# Define motifs
AP1 = "TGACTCAG"
EBOX = "CACGTGAC"

print("=== SYSTEMATIC MOTIF QUALITY CHECK ===")
print("Expected: exactly ONE AP-1 and ONE E-box per sequence")
print("Distance: 4-10 bp apart (non-overlapping)")
print()

# Analyze all sequences
def find_all_positions(seq, motif):
    positions = []
    start = 0
    while True:
        pos = seq.find(motif, start)
        if pos == -1:
            break
        positions.append(pos)
        start = pos + 1
    return positions

def check_overlap(pos1, len1, pos2, len2):
    """Check if two intervals overlap."""
    return not (pos1 + len1 <= pos2 or pos2 + len2 <= pos1)

# Check train set
train_set = sequences[sequences['split'] == 'train']
print(f"=== TRAIN SET (n={len(train_set)}) ===")

train_issues = {
    'multiple_ap1': 0,
    'multiple_ebox': 0,
    'missing_ap1': 0,
    'missing_ebox': 0,
    'overlapping': 0,
    'distance_too_close': 0,
    'distance_too_far': 0,
    'total_problematic': 0
}

for idx, row in train_set.iterrows():
    seq = row['sequence']
    ap1_positions = find_all_positions(seq, AP1)
    ebox_positions = find_all_positions(seq, EBOX)

    # Check counts
    if len(ap1_positions) != 1:
        if len(ap1_positions) == 0:
            train_issues['missing_ap1'] += 1
        else:
            train_issues['multiple_ap1'] += 1
        train_issues['total_problematic'] += 1

    if len(ebox_positions) != 1:
        if len(ebox_positions) == 0:
            train_issues['missing_ebox'] += 1
        else:
            train_issues['multiple_ebox'] += 1
        train_issues['total_problematic'] += 1

    # Check overlap and distance (if both present)
    if len(ap1_positions) == 1 and len(ebox_positions) == 1:
        ap1_pos = ap1_positions[0]
        ebox_pos = ebox_positions[0]

        if check_overlap(ap1_pos, len(AP1), ebox_pos, len(EBOX)):
            train_issues['overlapping'] += 1
            train_issues['total_problematic'] += 1
        else:
            distance = abs(ap1_pos - ebox_pos) - len(AP1)  # gap between motifs
            if distance < 4:
                train_issues['distance_too_close'] += 1
                train_issues['total_problematic'] += 1
            elif distance > 10:
                train_issues['distance_too_far'] += 1
                train_issues['total_problematic'] += 1

for issue, count in train_issues.items():
    if issue != 'total_problematic':
        print(f"  {issue}: {count}")
print(f"  Total problematic sequences: {train_issues['total_problematic']}")
print()

# Check test set
test_set = sequences[sequences['split'] == 'test']
print(f"=== TEST SET (n={len(test_set)}) ===")

test_issues = {
    'multiple_ap1': 0,
    'multiple_ebox': 0,
    'missing_ap1': 0,
    'missing_ebox': 0,
    'overlapping': 0,
    'distance_too_close': 0,
    'distance_too_far': 0,
    'total_problematic': 0
}

for idx, row in test_set.iterrows():
    seq = row['sequence']
    ap1_positions = find_all_positions(seq, AP1)
    ebox_positions = find_all_positions(seq, EBOX)

    # Check counts
    if len(ap1_positions) != 1:
        if len(ap1_positions) == 0:
            test_issues['missing_ap1'] += 1
        else:
            test_issues['multiple_ap1'] += 1
        test_issues['total_problematic'] += 1

    if len(ebox_positions) != 1:
        if len(ebox_positions) == 0:
            test_issues['missing_ebox'] += 1
        else:
            test_issues['multiple_ebox'] += 1
        test_issues['total_problematic'] += 1

    # Check overlap and distance (if both present)
    if len(ap1_positions) >= 1 and len(ebox_positions) >= 1:
        # For multiple motifs, check the closest pair
        min_distance = float('inf')
        for ap1_pos in ap1_positions:
            for ebox_pos in ebox_positions:
                if check_overlap(ap1_pos, len(AP1), ebox_pos, len(EBOX)):
                    test_issues['overlapping'] += 1
                    test_issues['total_problematic'] += 1
                    break
                else:
                    distance = abs(ap1_pos - ebox_pos) - len(AP1)
                    min_distance = min(min_distance, distance)

        # Only check distance if we didn't already count overlapping
        if not check_overlap(ap1_positions[0], len(AP1), ebox_positions[0], len(EBOX)):
            if min_distance < 4:
                test_issues['distance_too_close'] += 1
                test_issues['total_problematic'] += 1
            elif min_distance > 10:
                test_issues['distance_too_far'] += 1
                test_issues['total_problematic'] += 1

for issue, count in test_issues.items():
    if issue != 'total_problematic':
        print(f"  {issue}: {count}")
print(f"  Total problematic sequences: {test_issues['total_problematic']}")
print()

print("=== SUMMARY ===")
print(f"Train set quality: {800 - train_issues['total_problematic']}/800 conforming")
print(f"Test set quality: {200 - test_issues['total_problematic']}/200 conforming")

if test_issues['overlapping'] > 0 or test_issues['multiple_ebox'] > 0:
    print()
    print("⚠️ WARNING: Test set has motif specification violations")
    if test_issues['overlapping'] > 0:
        print(f"   - {test_issues['overlapping']} sequence(s) with overlapping motifs")
    if test_issues['multiple_ebox'] > 0:
        print(f"   - {test_issues['multiple_ebox']} sequence(s) with multiple E-box copies")
